function f79CompararStockTurnos({productos,movimientos,turnos,ventas=[],q='',rubro=''}){
  const seleccion=(turnos||[]).filter(Boolean).map(t=>({...t,id:String(t.id),ini:Date.parse(t.desde),fin:Date.parse(t.hasta)}));
  const min=Math.min(...seleccion.map(t=>t.ini)),max=Math.max(...seleccion.map(t=>t.fin));
  const claves=new Set(seleccion.map(t=>t.id)),porProducto=new Map(),ids=new Set(),sinTurno=[],conVenta=new Set(),cantidadVentas=new Map();
  // Índice efímero: cada consulta incorpora ediciones, anulaciones y sincronizaciones nuevas.
  (movimientos||[]).forEach(m=>{
    if(!m)return;
    const id=m.prodId,turno=f6ClaveTurno(m),fecha=Date.parse(m.fecha);
    const registro={mov:m,turno,fecha,recibido:Date.parse(m._v4receivedAt)};
    if(!porProducto.has(id))porProducto.set(id,[]);
    porProducto.get(id).push(registro);
    const enPeriodo=fecha>=min&&fecha<=max;
    if(id&&(claves.has(turno)||enPeriodo))ids.add(id);
    if(!turno&&enPeriodo)sinTurno.push(m);
    if(m.tipo==='venta')conVenta.add(turno);
  });
  (ventas||[]).forEach(v=>{const id=f6ClaveTurno(v);cantidadVentas.set(id,(cantidadVentas.get(id)||0)+1);});
  const incompletos=seleccion.filter(t=>Number(t.cantVentas)>0&&((cantidadVentas.get(t.id)||0)<Number(t.cantVentas)||!conVenta.has(t.id))).map(t=>t.id);
  const catalogo=[...(productos||[])],enCatalogo=new Set(catalogo.map(p=>p.id));
  ids.forEach(id=>{if(!enCatalogo.has(id)){catalogo.push({id,nombre:'Producto no disponible',rubro:'',stockBase:null,ausente:true});enCatalogo.add(id);}});
  const round=n=>Math.round((n+Number.EPSILON)*1000000)/1000000;
  const filas=filtrarProductosPorBusqueda(catalogo,q,rubro).filter(p=>ids.has(p.id)).map(producto=>({producto,
    turnos:seleccion.map(t=>{
      let ingresos=0,ventas=0,ajustes=0,neto=0,externos=0,inicio=Number(producto.stockBase)||0,final=inicio,tardios=0,fueraDeHorario=false;
      const propios=[];
      // El grupo conserva el orden original, incluso en las sumas de cantidades por peso.
      (porProducto.get(producto.id)||[]).forEach(r=>{
        const m=r.mov,cant=Number(m.cant)||0;
        if(r.turno===t.id){
          propios.push(m);neto+=cant;
          if(m.tipo==='ingreso')ingresos+=cant;else if(m.tipo==='venta')ventas+=cant;else ajustes+=cant;
          if(r.recibido>t.fin)tardios++;
          if(!Number.isFinite(r.fecha)||r.fecha<t.ini||r.fecha>t.fin)fueraDeHorario=true;
        }else if(r.fecha>=t.ini&&r.fecha<=t.fin)externos+=cant;
        if(Number.isFinite(r.fecha)){
          if(r.fecha<t.ini)inicio+=cant;
          if(r.fecha<=t.fin)final+=cant;
        }
      });
      return {ingresos:round(ingresos),vendidas:-round(ventas),ajustes:round(ajustes),neto:round(neto),externos:round(externos),
        inicio:producto.stockBase==null||t.aperturaAproximada||incompletos.length||!Number.isFinite(t.ini)?null:round(inicio),
        final:producto.stockBase==null||incompletos.length||!Number.isFinite(t.fin)?null:round(final),
        tardios,fueraDeHorario,movs:propios};
    })})).sort((a,b)=>String(a.producto.nombre).localeCompare(String(b.producto.nombre),'es'));
  return {filas,incompletos,sinTurno};
}

